/// # Errors
/// - Bad stage arg
/// - Bad config path
/// - Bad config shape
/// - Missing or non-Unicode `DATABASE_URL` for commands that use the database
/// - Service level failures
pub async fn run_cli(args: DataArgs) -> anyhow::Result<()> {
    match args.command {
        DataCommands::Latest { config } => {
            let config = LoaderConfig::try_from(&config)?;
            match ExposedDataPipeline::latest_ingestion(&config.data_dir).await? {
                Some((path, key)) => {
                    println!("Ingestion key: {key}");
                    println!("Path: {}", path.display());
                }
                None => println!("No ingestion runs found."),
            }
        }
        DataCommands::Declarations {
            stage,
            config,
            ingestion_key,
        } => match DeclarationIngestionStage::from_str(&stage)? {
            DeclarationIngestionStage::Fetch => {
                let config = DeclarationFetcherConfig::try_from(&config)?;
                let data_config = DataConfig::from_env()?;
                let api = ParliamentApiClient::new(config.batch_size)?;
                let db = ExposedDatabase::new(&data_config.connection_string).await;
                let fs = ExposedDataPipeline::new_with_ingestion_key(
                    &config.data_dir,
                    ingestion_key.unwrap_or_default(),
                )?;
                DeclarationFetcherService::new(db, api, fs)
                    .fetch_declarations()
                    .await?;
            }
            DeclarationIngestionStage::Resolve => {
                let ingestion_key = ingestion_key.ok_or_else(|| {
                    anyhow::anyhow!("declarations resolve requires --ingestion-key")
                })?;
                let config = DeclarationResolverConfig::try_from(&config)?;
                let storage = ExposedDataPipeline::open_cleaned_declarations(
                    &config.data_dir,
                    ingestion_key.clone(),
                )?;
                let scorer = SplinkScorer::new(config.resolution_python, config.resolution_worker)?;
                let summary =
                    DeclarationResolverService::new(storage, scorer, config.candidate_budget)
                        .resolve_declarations()
                        .await?;
                println!("Ingestion key: {ingestion_key}");
                println!(
                    "Resolved declarations: {}",
                    std::path::absolute(config.data_dir)?
                        .join(ingestion_key.to_string())
                        .join("resolved/declarations")
                        .display()
                );
                println!("Observations: {}", summary.observations);
                println!("Funding occurrences: {}", summary.payments);
                println!("Pair decisions: {}", summary.pairs);
            }
            DeclarationIngestionStage::Load => {
                let ingestion_key = ingestion_key
                    .ok_or_else(|| anyhow::anyhow!("declarations load requires --ingestion-key"))?;
                let config = LoaderConfig::try_from(&config)?;
                let data_config = DataConfig::from_env()?;
                let storage = ExposedDataPipeline::open_resolved_declarations(
                    &config.data_dir,
                    ingestion_key.clone(),
                )?;
                let db = ExposedDatabase::new(&data_config.connection_string).await;
                let summary = DeclarationLoaderService::new(storage, db)
                    .load_declarations()
                    .await?;
                println!("Ingestion key: {ingestion_key}");
                match summary.outcome {
                    crate::domain::models::declaration_loading::DeclarationLoadOutcome::Imported => {
                        println!("Loaded declarations: {}", summary.declarations);
                    }
                    crate::domain::models::declaration_loading::DeclarationLoadOutcome::AlreadyLoaded => {
                        println!("Run already loaded. Declarations: {}", summary.declarations);
                    }
                }
                println!("Resolved identities: {}", summary.funders);
                println!("Funding occurrences: {}", summary.funding_entries);
            }
            DeclarationIngestionStage::Clean => {
                let ingestion_key = ingestion_key.ok_or_else(|| {
                    anyhow::anyhow!("declarations clean requires --ingestion-key")
                })?;
                let config = LoaderConfig::try_from(&config)?;
                let fs = ExposedDataPipeline::open_existing_declarations(
                    &config.data_dir,
                    ingestion_key.clone(),
                )?;
                let summary = DeclarationCleanerService::new(fs)
                    .clean_declarations()
                    .await?;
                println!("Ingestion key: {ingestion_key}");
                println!(
                    "Cleaned declarations: {}",
                    std::path::absolute(&config.data_dir)?
                        .join(ingestion_key.to_string())
                        .join("cleaned/declarations")
                        .display()
                );
                println!("Member partitions: {}", summary.member_partitions);
                println!("Declarations: {}", summary.declarations);
                println!("Funding entries: {}", summary.funding_entries);
                println!("Funder observations: {}", summary.funders);
            }
        },
        DataCommands::Members {
            stage,
            config,
            ingestion_key,
        } => {
            let stage = MemberIngestionStage::from_str(&stage)?;
            let ingestion_key = ingestion_key.unwrap_or_default();
            match stage {
                MemberIngestionStage::Fetch => {
                    let config = FetcherConfig::try_from(&config)?;
                    let api = ParliamentApiClient::new(config.batch_size)?;
                    let fs = ExposedDataPipeline::new_with_ingestion_key(
                        &config.data_dir,
                        ingestion_key,
                    )?;
                    let service = FetcherService::new(fs, api);

                    let req = EntityIngestionRequest {};
                    service.fetch_members(&req).await?;
                }
                MemberIngestionStage::Load => {
                    let config = LoaderConfig::try_from(&config)?;
                    let data_config = DataConfig::from_env()?;
                    let fs = ExposedDataPipeline::new_with_ingestion_key(
                        &config.data_dir,
                        ingestion_key,
                    )?;
                    let db = ExposedDatabase::new(&data_config.connection_string).await;
                    let service = IngesterService::new(fs, db);

                    service.load_members().await?;
                }
            }
        }
    }
    Ok(())
}
//! Deserialize and project the Interests API response.

use chrono::Utc;
use serde::Deserialize;
use serde_json::Value;

use super::{ApiError, ParliamentApiClient};
use crate::domain::models::declaration_ingestion::{CapturedDeclaration, MemberAsId};
use crate::outbound::declaration_source::decode_declaration;

const INTERESTS_URL: &str = "https://interests-api.parliament.uk/api/v2/Interests";

impl ParliamentApiClient {
    pub(super) async fn capture_declarations(
        &self,
        member: MemberAsId,
    ) -> Result<Vec<CapturedDeclaration>, ApiError> {
        let mut declarations = Vec::new();
        let mut offset = 0;
        loop {
            let url = format!(
                "{INTERESTS_URL}?MemberId={}&Type=Commons&ExcludeExpired=false&ExpandChildInterests=false&Skip={offset}&Take={}",
                member.parliament_member_id(),
                self.batch_size,
            );
            let bytes = self.client.get(url).send().await?.bytes().await?;
            let response: InterestPage = serde_json::from_slice(&bytes)?;
            if response.items.is_empty() {
                break;
            }
            let fetched_at = Utc::now();
            offset += response.items.len();
            for source in response.items {
                declarations.push(decode_declaration(source, fetched_at)?);
            }
            if offset >= response.total_results {
                break;
            }
        }
        Ok(declarations)
    }
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct InterestPage {
    total_results: usize,
    // Retain every source field alongside the typed projection below.
    items: Vec<Value>,
}
# Run declaration resolution

Use Python 3.10 or later. Install the statistical runtime before invoking the CLI. From the repository root, create a Python environment and install the pinned package dependencies:

```sh
python3 -m venv resolution/.venv
resolution/.venv/bin/python -m pip install ./resolution
```

The package pins Splink 4.0.17 and DuckDB 1.4.4. The repository worker script calls the packaged scorer. No packages are installed at resolution runtime. The bundled frozen model supplies every comparison parameter. Its probabilities are computed but uncalibrated.

Configure an explicit interpreter and the ingestion data directory:

```yaml
data_dir: data
resolution_python: resolution/.venv/bin/python
resolution_worker: resolution/worker.py
candidate_budget: 1000000
```

Paths are relative to the invocation directory. `resolution_worker` defaults to `resolution/worker.py`, so invoke from the repository root or supply an absolute path. The budget applies to profile candidates and expanded source-observation pairs. Increase it explicitly when the command refuses a larger candidate set.

Resolve an existing cleaned run:

```sh
cargo run --package exposed --bin exposed -- data declarations resolve exposed/config/declaration-resolution-dev.yaml --ingestion-key UUID
```

The command prints the output path and counts. The bundle contains observation resolutions, payment attributions, candidate decisions, and a manifest. It refuses an existing bundle. Older cleaned schemas require cleaning retained raw capture into a fresh run. Raw files are not needed after the current cleaner has produced the checked pair.

Run worker integration tests against actual Splink:

```sh
resolution/.venv/bin/python -m unittest discover -s resolution/tests -v
```

Run the real CLI test with a build environment that supplies `DATABASE_URL` or the SQLx query cache for existing database adapters:

```sh
EXPOSED_RESOLUTION_PYTHON="$PWD/resolution/.venv/bin/python" cargo test --package exposed --test declaration_resolution_cli -- --ignored
```

This test builds and invokes the current CLI, cleans retained raw evidence, and resolves two charity observations with statistical support and four Gary Lubner donor observations with missing or disagreeing addresses. It checks the actual names in each identity, the real Splink scores, and refusal to overwrite the result. It removes raw evidence before resolution to verify that the resolver reads only cleaned inputs.

Policy `funder-resolution-v3` uses cleaner-extracted aliases and organization-name evidence, punctuation-normalized numbered-street addresses, and typed candidate keys for aliases and `Unite` trade unions. HSBC's CEO-annotated bank name can link to its legal bank name when distinctive organization terms and the numbered-street address agree. Regional and branch spellings with an explicit `Trade Union` kind and the `Unite` root can resolve to one funder identity. Person/organization conflicts and competing company numbers still block merges; ambiguous fuzzy names stay review candidates. Each named singleton receives a separate provisional run-local identity. See the [resolution policy](../docs/funder-resolution-design.md) for attribution and repeat behavior.
use clap::{Parser, Subcommand};
use exposed::inbound::{
    cli::{DataArgs, run_cli},
    http::server::run_server,
};

#[derive(Parser)]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand)]
enum Commands {
    Server,
    Data(DataArgs),
}

fn main() -> anyhow::Result<()> {
    let args = Cli::parse();
    match args.command {
        Commands::Server => run_server(),
        Commands::Data(args) => {
            dotenvy::dotenv().ok();
            tokio::runtime::Runtime::new()?.block_on(run_cli(args))
        }
    }
}
"}

