            i64::try_from(summary.funders).map_err(db_error)?,
            i64::try_from(summary.funding_entries).map_err(db_error)?
        ).execute(&mut *tx).await.map_err(db_error)?;
        tx.commit().await.map_err(db_error)?;
        Ok(summary)
    }
