    declarations BIGINT NOT NULL CHECK (declarations >= 0),
    funders BIGINT NOT NULL CHECK (funders >= 0),
    funding_entries BIGINT NOT NULL CHECK (funding_entries >= 0),
    loaded_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

